<?php
namespace qqworld_collector; class upgrade { public function __construct() { add_action( 'qqworld-collector-register-activation-hook', array($this, 'wipe') ); add_action( 'qqworld-collector-register-activation-hook', array($this, 'custom_upload_dir') ); } public function wipe() { global $wpdb; $sql = "SELECT `meta_id` FROM `{$wpdb->postmeta}` WHERE `meta_key`='qqworld-auto-save-images-posts-scanned' LIMIT 1"; $rows = $wpdb->get_results($sql); if (count($rows)) { $sql = "UPDATE `{$wpdb->postmeta}` SET `meta_key`='qqworld-collector-auto-save-attachments-posts-scanned' WHERE `meta_key`='qqworld-auto-save-images-posts-scanned'"; $wpdb->update( $wpdb->postmeta, array( 'meta_key' => 'qqworld-collector-auto-save-attachments-posts-scanned' ), array( 'meta_key' => 'qqworld-auto-save-images-posts-scanned' ), array( '%s' ), array( '%s' ) ); } } public function custom_upload_dir() { $list = array( 'ftp' => 'ftp', 'aliyun-oss' => 'oss', 'tencent-cos' => 'cos', 'baidu-bos' => 'bos', 'ucloud-ufile' => 'ucloud_ufile', 'upyun' => 'upyun', 'qiniu' => 'qiniu' ); $cloud_storage = get_option( 'qqworld-collector-cloud-storage-settings' ); foreach ($list as $slug => $var_name) { $var = 'cloud_storage_' . $var_name . '_custom_upload_dir'; $custom_upload_dir = $GLOBALS['QC']->options->$var; $var = 'cloud_storage_' . $var_name . '_folder'; echo $var . "\n"; $folder = $custom_upload_dir = $GLOBALS['QC']->options->$var; $dirs = wp_upload_dir(); $path = $dirs['basedir']; $default_upload_dir = '/' . str_replace(ABSPATH, '', $path); if ($custom_upload_dir != 1 && $default_upload_dir != $folder) { $cloud_storage[$slug]['custom-upload-dir'] = 1; } } update_option( 'qqworld-collector-cloud-storage-settings', $cloud_storage ); } } new upgrade; ?>